package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DynamicallyRegisteredVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property dynamically registered of trusted client ")
  void test_dynamically_registered_v_o_builder() {
    Assertions.assertFalse(DynamicallyRegisteredVO.nullValue().isDynamicallyRegistered(),
        "A empty vo should have a null value");
    Assertions.assertFalse(DynamicallyRegisteredVO.tryFrom(null).isDynamicallyRegistered(),
        "With a null value, no present result");
    Assertions.assertEquals(true, DynamicallyRegisteredVO.from(true).isDynamicallyRegistered());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DynamicallyRegisteredVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", DynamicallyRegisteredVO.from(true).toString());
  }
}
